using QuantForge.Core;namespace QuantForge.Core.ArchitectureTests;public sealed class StrategyDraftFileStoreTests{[Fact]public void Draft_round_trips_with_identity_validation(){var root=Path.Combine(Path.GetTempPath(),Guid.NewGuid().ToString("N"));try{var d=StrategyDraftRules.Create("s","ABC",new[]{new StrategyDraftParameter("n","1")});var store=new StrategyDraftFileStore(root);store.Save(d);Assert.Equal(d,store.Load(d.DraftFingerprint));}finally{if(Directory.Exists(root))Directory.Delete(root,true);}}}
